declare(strict_types=1);
if(PHP_SAPI!=='cli')exit;
foreach(['AdminAuth','Pricing','Orders'] as $class)require_once dirname(__DIR__).'/src/'.$class.'.php';
function exportCheck(bool $ok,string $message):void{if(!$ok)throw new RuntimeException($message);}
function exportBad(callable $fn):void{try{$fn();}catch(HttpError $e){exportCheck($e->status===400,$e->getMessage());return;}throw new RuntimeException('Expected invalid filter/export');}
$dsn=getenv('JINGO_TEST_DSN');if(!$dsn)exit(1);$opts=[PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION,PDO::ATTR_DEFAULT_FETCH_MODE=>PDO::FETCH_ASSOC,PDO::ATTR_EMULATE_PREPARES=>false];$user=getenv('JINGO_TEST_USER')?:'root';$password=getenv('JINGO_TEST_PASSWORD')?:'';$server=new PDO($dsn,$user,$password,$opts);$name='jingo_export_test_'.bin2hex(random_bytes(6));$server->exec("CREATE DATABASE `$name` CHARACTER SET utf8mb4");$db=null;
try{
 $db=new PDO($dsn.';dbname='.$name,$user,$password,$opts);$db->exec("SET time_zone='+00:00'");foreach(glob(dirname(__DIR__).'/database/*.sql') as $file)foreach(explode(';',file_get_contents($file)) as $sql)if(trim($sql)!=='')$db->exec($sql);$orders=new Orders($db);
 $snapshot=['productName'=>"Vé, \"đẹp\" 🐴\nDòng hai",'variantName'=>'Gói gốc','date'=>'2026-12-01','total'=>80,'lines'=>[['customerType'=>'ADULT','quantity'=>1],['customerType'=>'LOCAL_ADULT','quantity'=>2],['customerType'=>'LOCAL_CHILD','quantity'=>1],['customerType'=>'SENIOR','quantity'=>1]],'timeSlot'=>['start'=>'09:00','end'=>'10:00'],'discount'=>['code'=>'SAVE','amount'=>10,'subtotal'=>100],'onlineDiscount'=>['amount'=>10,'subtotal'=>90]];
 $contact=['name'=>'  =HYPERLINK("x")','phone'=>'0901234567','email'=>'csv@example.test'];$insert=$db->prepare("INSERT INTO jingo_orders(id,code,request_id,request_hash,access_hash,snapshot,contact,instructions,created_at,booking_status,payment_status) VALUES (?,?,?,?,?,?,?,'',?,?,?)");
 $seed=function(int $n,string $time,string $booking='CONFIRMED',string $payment='PAID')use($insert,$snapshot,$contact):string{$id='00000000-0000-4000-8000-'.str_pad((string)$n,12,'0',STR_PAD_LEFT);$insert->execute([$id,'JG'.str_pad(strtoupper(dechex($n)),10,'0',STR_PAD_LEFT),$id,str_repeat('a',64),str_repeat('b',64),json_encode($snapshot),json_encode($contact),$time,$booking,$payment]);return $id;};
 $seed(1,'2026-11-12 16:59:59');$seed(2,'2026-11-12 17:00:00');$seed(3,'2026-11-13 16:59:59');$seed(4,'2026-11-13 17:00:00');$archived=$seed(5,'2026-11-12 17:00:00','CANCELLED','UNPAID');$db->prepare("INSERT INTO jingo_order_archives(order_id,archived_by,reason) VALUES (?,'admin','Test')")->execute([$archived]);
 $filter=['from'=>'2026-11-13','to'=>'2026-11-13'];$report=$orders->export($filter);exportCheck(count($report['rows'])===2&&$report['rows'][0]['code']==='JG0000000003','Vietnam date boundaries/order');exportCheck($orders->list($filter)['summary']['total']===2,'List/export filters differ');exportCheck(count($orders->export(['dateKind'=>'VISIT','from'=>'2026-12-01','to'=>'2026-12-01'])['rows'])===4,'Visit date inclusive');exportCheck($orders->export(['dateKind'=>'VISIT','to'=>'2026-11-30'])['rows']===[],'Visit boundary');exportCheck(count($orders->export(['page'=>2,'pageSize'=>1])['rows'])===4,'Export only one page');
 foreach([['from'=>'2026-02-30'],['from'=>'2026-12-02','to'=>'2026-12-01'],['dateKind'=>'no'],['q'=>[]],['from'=>[]],['booking'=>'invalid'],['archived'=>'yes'],['secret'=>'x']] as $bad){exportBad(fn()=>$orders->export($bad));exportBad(fn()=>$orders->list($bad));}
 exportCheck(count($orders->export(['q'=>'CSV@EXAMPLE.TEST'])['rows'])===4,'Case-insensitive literal search');exportCheck($orders->export(['q'=>'%'])['rows']===[],'Wildcard search broadened');exportCheck($orders->export(['payment'=>'UNPAID'])['rows']===[],'Payment filter');$archive=$orders->export(['archived'=>'true','booking'=>'CANCELLED']);exportCheck(count($archive['rows'])===1&&$archive['archived'],'Archive isolation');
 $csv=Orders::csv($report);exportCheck(str_starts_with($csv,"\xEF\xBB\xBF")&&str_ends_with($csv,"\r\n"),'CSV BOM/CRLF');$stream=fopen('php://temp','r+');fwrite($stream,substr($csv,3));rewind($stream);$header=fgetcsv($stream,0,',','"','');$row=fgetcsv($stream,0,',','"','');fclose($stream);exportCheck(count($header)===21&&count($row)===21,'Original 21 columns');exportCheck($row[1]==='2026-11-13 23:59:59'&&$row[2]==="'".$contact['name']&&$row[3]==="'0901234567",'Date/formula/phone');exportCheck($row[5]===$snapshot['productName']&&$row[8]==='09:00 – 10:00','CSV Unicode/quoting/multiline');exportCheck(array_slice($row,9,5)===['3','1','1','5','80'],'Local groups/guest totals');exportCheck(array_slice($row,18)===['SAVE','20','90'],'Discount fields');exportCheck(!str_contains($csv,'access_hash')&&!str_contains($csv,'instructions'),'Private technical fields');exportCheck(str_contains(Orders::csv($archive),'"Có"'),'Archived marker');
 foreach(['+SUM(1)','-1','@evil',"\ttext", "\ntext", "\xEF\xBB\xBF =1"] as $formula){$r=$report;$c=$contact;$c['name']=$formula;$r['rows'][0]['contact']=json_encode($c);exportCheck(str_contains(Orders::csv($r),'"\''.$formula.'"'),'Formula guard');}
 exportCheck(substr_count(Orders::csv(['rows'=>[],'archived'=>false]),"\r\n")===1,'Empty CSV');
 $db->beginTransaction();for($i=6;$i<=10002;$i++)$seed($i,'2026-11-12 17:00:00');$db->commit();exportBad(fn()=>$orders->export([]));$db->exec("DELETE FROM jingo_orders WHERE code IN ('JG0000002712')");exportCheck(count($orders->export([])['rows'])===10000,'Exact export limit');
 echo "PASS: order export/filter parity, GMT+7 and visit boundaries, archive/search/payment, complete results, CSV 21 columns/Unicode/phone/formula/discount, 10000 limit.\n";
}finally{if($db&&$db->inTransaction())$db->rollBack();$db=null;$server->exec("DROP DATABASE `$name`");}
